static void watchdog_task(void *p)
{
    (void)p;
    for (;;) {
        if (ulTaskNotifyTake(pdTRUE, g_T) == 0) {
            printf("[t=%u] WATCHDOG RESET\n", (unsigned)xTaskGetTickCount());
            g_wdg = NULL;
            vTaskDelete(NULL);
